-- Run inside BEGIN / ROLLBACK. All fixtures are disposable within this transaction.
CREATE TEMP TABLE tt_flow_checks(name text,passed boolean);
GRANT SELECT,INSERT ON tt_flow_checks TO authenticated;
CREATE FUNCTION pg_temp.reject_flow(q text) RETURNS boolean LANGUAGE plpgsql AS $$BEGIN BEGIN EXECUTE q;EXCEPTION WHEN OTHERS THEN RETURN true;END;RAISE EXCEPTION 'Expected rejection: %',q;END $$;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT id FROM auth.users LIMIT 1),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
WITH a AS(INSERT INTO public.trading_accounts(account_name,account_type,default_instrument,default_quantity) VALUES('TEMP_FLOW_A','demo','MNQ',1) RETURNING id) SELECT set_config('tt736.a',id::text,true) FROM a;
WITH a AS(INSERT INTO public.trading_accounts(account_name,account_type,default_instrument,default_quantity) VALUES('TEMP_FLOW_B','demo','NQ',1) RETURNING id) SELECT set_config('tt736.b',id::text,true) FROM a;
WITH s AS(INSERT INTO public.trading_sessions(session_date,status,htf_context) VALUES('2099-04-01','open',jsonb_build_object('selected_accounts',jsonb_build_array(jsonb_build_object('account_id',current_setting('tt736.a')),jsonb_build_object('account_id',current_setting('tt736.b'))))) RETURNING id) SELECT set_config('tt736.s',id::text,true) FROM s;
SELECT set_config('tt736.alloca',jsonb_build_array(jsonb_build_object('account_id',current_setting('tt736.a'),'role','leader','instrument','MNQ','planned_quantity',1,'initial_sl_ticks',40))::text,true);
SELECT set_config('tt736.allocb',jsonb_build_array(jsonb_build_object('account_id',current_setting('tt736.b'),'role','leader','instrument','NQ','planned_quantity',1,'initial_sl_ticks',20))::text,true);
SELECT set_config('tt736.ctx','{"execution_mode":"independent","emotion_scales":{"focus":7,"pressure":3}}',true);
SELECT set_config('tt736.plan','{"thesis":"Zone hält","trigger_condition":"Absorption bestätigt","invalidation":"Zone gebrochen"}',true);
SELECT set_config('tt736.req',gen_random_uuid()::text,true);
SELECT set_config('tt736.trade',public.record_trade_attempt_v736(current_setting('tt736.s')::uuid,'TEST','MNQ','long',current_setting('tt736.alloca')::jsonb,'unreported',current_setting('tt736.req')::uuid,'Testausnahme',null,null,current_setting('tt736.ctx')::jsonb,current_setting('tt736.plan')::jsonb)::text,true);
INSERT INTO tt_flow_checks SELECT 'new_idea_and_risk_atomic',initial_risk_usd=20 AND observations->'entry_context_v736'->'emotion_scales'->>'focus'='7' AND EXISTS(SELECT 1 FROM public.trade_ideas_v733 WHERE id=current_setting('tt736.req')::uuid) FROM public.trades WHERE id=current_setting('tt736.trade')::uuid;
INSERT INTO tt_flow_checks SELECT 'retry_same_trade',public.record_trade_attempt_v736(current_setting('tt736.s')::uuid,'TEST','MNQ','long',current_setting('tt736.alloca')::jsonb,'unreported',current_setting('tt736.req')::uuid,'Testausnahme',null,null,current_setting('tt736.ctx')::jsonb,current_setting('tt736.plan')::jsonb)=current_setting('tt736.trade')::uuid;
SELECT set_config('tt736.other',public.record_trade_attempt_v736(current_setting('tt736.s')::uuid,'TEST','NQ','short',current_setting('tt736.allocb')::jsonb,'unreported',gen_random_uuid(),'Testausnahme',null,null,current_setting('tt736.ctx')::jsonb)::text,true);
INSERT INTO tt_flow_checks SELECT 'independent_second_account',count(*)=1 AND bool_and(account_id=current_setting('tt736.b')::uuid) FROM public.trade_account_allocations WHERE trade_id=current_setting('tt736.other')::uuid;
SELECT set_config('tt736.copy',(current_setting('tt736.alloca')::jsonb||jsonb_build_array(jsonb_build_object('account_id',current_setting('tt736.b'),'role','follower','instrument','NQ','planned_quantity',1,'initial_sl_ticks',20)))::text,true);
SELECT set_config('tt736.copied',public.record_trade_attempt_v736(current_setting('tt736.s')::uuid,'TEST','MNQ','long',current_setting('tt736.copy')::jsonb,'unreported',gen_random_uuid(),'Testausnahme',null,null,'{"execution_mode":"copy","emotion_scales":{}}')::text,true);
INSERT INTO tt_flow_checks SELECT 'copy_allocations_and_risk',count(*)=2 AND sum(initial_risk_usd)=120 FROM public.trade_account_allocations WHERE trade_id=current_setting('tt736.copied')::uuid;
INSERT INTO tt_flow_checks SELECT 'independent_multi_rejected',pg_temp.reject_flow(format('SELECT public.record_trade_attempt_v736(%L,''TEST'',''MNQ'',''long'',%L,''unreported'',gen_random_uuid(),null,null,null,%L)',current_setting('tt736.s'),current_setting('tt736.copy'),current_setting('tt736.ctx')));
INSERT INTO tt_flow_checks SELECT 'changed_retry_rejected',pg_temp.reject_flow(format('SELECT public.record_trade_attempt_v736(%L,''TEST'',''MNQ'',''long'',%L,''unreported'',%L,''Testausnahme'',null,null,''{"execution_mode":"independent","emotion_scales":{"focus":8}}'',%L)',current_setting('tt736.s'),current_setting('tt736.alloca'),current_setting('tt736.req'),current_setting('tt736.plan')));
INSERT INTO tt_flow_checks SELECT 'entry_ratings_immutable',pg_temp.reject_flow(format('UPDATE public.trades SET observations=observations-''entry_context_v736'' WHERE id=%L',current_setting('tt736.trade')));
INSERT INTO tt_flow_checks SELECT 'invalid_rating_rejected',NOT public.valid_emotion_scales_v736('{"focus":11}') AND NOT public.valid_emotion_scales_v736('{"fear":1.5}') AND NOT public.valid_emotion_scales_v736('{"unknown":5}');
SELECT public.close_trade_with_scales_v736(current_setting('tt736.trade')::uuid,'TP',(SELECT jsonb_agg(jsonb_build_object('allocation_id',id,'realized_pnl_usd',30,'fees_usd',1)) FROM public.trade_account_allocations WHERE trade_id=current_setting('tt736.trade')::uuid),'{"fear":2,"relief":8}');
INSERT INTO tt_flow_checks SELECT 'exit_and_scales_atomic',exit_at IS NOT NULL AND realized_pnl_usd=30 AND observations->'exit_emotion_scales'->>'relief'='8' FROM public.trades WHERE id=current_setting('tt736.trade')::uuid;
UPDATE public.trades SET observations=observations||'{"during_emotion_scales":{"fear":4,"greed":2}}'::jsonb WHERE id=current_setting('tt736.other')::uuid;
INSERT INTO tt_flow_checks SELECT 'during_scales_saved',observations->'during_emotion_scales'->>'fear'='4' FROM public.trades WHERE id=current_setting('tt736.other')::uuid;

INSERT INTO tt_flow_checks SELECT 'session_numbers_unique_and_ordered',count(*)=3 AND count(distinct session_trade_no)=3 AND min(session_trade_no)=1 AND max(session_trade_no)=3 FROM public.trades WHERE session_id=current_setting('tt736.s')::uuid;
INSERT INTO tt_flow_checks SELECT 'trade_number_immutable',pg_temp.reject_flow(format('UPDATE public.trades SET session_trade_no=99 WHERE id=%L',current_setting('tt736.trade')));
UPDATE public.trading_sessions SET htf_context=jsonb_set(htf_context,'{selected_accounts}',jsonb_build_array(jsonb_build_object('account_id',current_setting('tt736.a'),'instrument','MNQ','planned_quantity',1,'initial_sl_ticks',40))) WHERE id=current_setting('tt736.s')::uuid;
INSERT INTO tt_flow_checks SELECT 'configuration_changes_audited',jsonb_array_length(htf_context->'account_configuration_history')=2 AND htf_context->'account_configuration_history'->1->'previous'->0->>'account_id'=current_setting('tt736.a') FROM public.trading_sessions WHERE id=current_setting('tt736.s')::uuid;
UPDATE public.trading_sessions SET htf_context=jsonb_set(htf_context,'{account_configuration_history}','[]') WHERE id=current_setting('tt736.s')::uuid;
INSERT INTO tt_flow_checks SELECT 'configuration_history_cannot_be_erased',jsonb_array_length(htf_context->'account_configuration_history')=2 FROM public.trading_sessions WHERE id=current_setting('tt736.s')::uuid;
INSERT INTO tt_flow_checks SELECT 'setup_rules_shape',public.valid_setup_rules_v741('{"context":"Range","trigger":"Mein Trigger"}') AND NOT public.valid_setup_rules_v741('{"context":3}') AND NOT public.valid_setup_rules_v741('[]') AND NOT public.valid_setup_rules_v741('{"invented":"x"}');
SELECT set_config('tt741.goal',gen_random_uuid()::text,true);
SELECT public.set_training_focus_v735(current_setting('tt741.goal')::uuid,'Wenn Trigger fehlt, dann warte ich.',(SELECT id FROM public.training_goals_v7 WHERE owner_id=auth.uid() AND status='active'));
SELECT set_config('tt741.revised',gen_random_uuid()::text,true);
SELECT public.revise_training_focus_v741(current_setting('tt741.revised')::uuid,current_setting('tt741.goal')::uuid,'Wenn Trigger fehlt, dann warte ich auf meine Bestätigung.');
INSERT INTO tt_flow_checks SELECT 'focus_revision_preserves_history',(SELECT status='replaced' FROM public.training_goals_v7 WHERE id=current_setting('tt741.goal')::uuid) AND status='active' AND revised_from_id=current_setting('tt741.goal')::uuid FROM public.training_goals_v7 WHERE id=current_setting('tt741.revised')::uuid;
INSERT INTO tt_flow_checks SELECT 'focus_revision_retry_idempotent',(public.revise_training_focus_v741(current_setting('tt741.revised')::uuid,current_setting('tt741.goal')::uuid,'Wenn Trigger fehlt, dann warte ich auf meine Bestätigung.')).id=current_setting('tt741.revised')::uuid;
INSERT INTO tt_flow_checks SELECT 'stale_focus_revision_rejected',pg_temp.reject_flow(format('SELECT public.revise_training_focus_v741(gen_random_uuid(),%L,''Wenn Trigger fehlt, dann pausiere ich.'')',current_setting('tt741.goal')));

SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000099","role":"authenticated"}',true);
INSERT INTO tt_flow_checks SELECT 'foreign_session_rejected',pg_temp.reject_flow(format('SELECT public.record_trade_attempt_v736(%L,''TEST'',''MNQ'',''long'',%L,''unreported'',gen_random_uuid(),null,null,null,%L)',current_setting('tt736.s'),current_setting('tt736.alloca'),current_setting('tt736.ctx')));
RESET ROLE;
DO $$BEGIN IF EXISTS(SELECT 1 FROM tt_flow_checks WHERE passed IS NOT TRUE) THEN RAISE EXCEPTION 'Flow checks failed';END IF;END $$;
SELECT jsonb_agg(to_jsonb(t)) AS flow_checks FROM tt_flow_checks t;
